import pyomo.environ as pyo

DATA = {
    "foods": ["Eggs", "Chicken", "Tofu", "Salmon", "BrownRice", "Spinach"],
    "nutrients": ["protein", "carbs", "calories"],
    # cost per unit of each food ($)
    "cost": {
        "Eggs": 10,
        "Chicken": 9,
        "Tofu": 2,
        "Salmon": 10,
        "BrownRice": 8,
        "Spinach": 1,
    },
    # nutrient content per unit of each food
    "content": {
        "protein": {
            "Eggs": 1,
            "Chicken": 4,
            "Tofu": 13,
            "Salmon": 8,
            "BrownRice": 7,
            "Spinach": 8,
        },
        "carbs": {
            "Eggs": 13,
            "Chicken": 10,
            "Tofu": 9,
            "Salmon": 3,
            "BrownRice": 13,
            "Spinach": 16,
        },
        "calories": {
            "Eggs": 211,
            "Chicken": 256,
            "Tofu": 273,
            "Salmon": 54,
            "BrownRice": 93,
            "Spinach": 52,
        },
    },
    # minimum required daily intake per nutrient
    "requirement": {
        "protein": 60,
        "carbs": 122,
        "calories": 2028,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision: amount of each food to include (continuous, nonnegative)
    model.servings = pyo.Var(
        model.FOODS, within=pyo.NonNegativeReals, bounds=(0, None)
    )

    # Objective: minimise total grocery cost
    def obj_rule(m):
        return sum(d["cost"][f] * m.servings[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: meet at least the required amount of each nutrient
    def nutrient_rule(m, n):
        return (
            sum(d["content"][n][f] * m.servings[f] for f in m.FOODS)
            >= d["requirement"][n]
        )

    model.nutrient_requirement = pyo.Constraint(
        model.NUTRIENTS, rule=nutrient_rule
    )

    return model


