    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision variables: amount of each food purchased per day
    model.x = pyo.Var(
        model.FOODS,
        within=pyo.NonNegativeReals,
        bounds=(0, None),
    )

    # Objective: minimise total grocery cost
    def obj_rule(m):
        return sum(d["cost"][f] * m.x[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each nutrient must meet its minimum daily requirement (at least)
